const devMemory = new Memory({
  observationalMemory: {
    observation: {
      messageTokens: 500  // Trigger every 500 tokens
    }
  }
});

// Production: Efficient learning
const prodMemory = new Memory({
  observationalMemory: {
    observation: {
      messageTokens: 30000  // Trigger every 30,000 tokens
    }
  }
